import os
from ibm_watsonx_ai.client import APIClient
from ibm_watsonx_ai.foundation_models.model import Model
from ibm_watsonx_ai.foundation_models.parameters import TextGenerationParameters

def resolve_and_invoke_model(model_identifier: str, prompt: str) -> str:
    api_key = os.environ.get("WATSONX_API_KEY")
    project_id = os.environ.get("WATSONX_PROJECT_ID")
    if not api_key or not project_id:
        raise ValueError("WATSONX_API_KEY and WATSONX_PROJECT_ID environment variables must be set.")

    api_client = APIClient(api_key=api_key, project_id=project_id)

    resolved_deployment_id = None
    resolved_model_id_for_inference = None
    try:
        deployments_response = api_client.deployments.get_deployments(limit=100)
        deployments = deployments_response.get('results', [])

        for dep in deployments:
            if dep.get('status') == 'ready':
                serving_model_info = dep.get('serving_model', {})
                if serving_model_info.get('model_id') == model_identifier:
                    resolved_deployment_id = dep.get('deployment_id')
                    resolved_model_id_for_inference = serving_model_info.get('model_id')
                    break
                elif model_identifier.lower() in dep.get('name', '').lower() and serving_model_info.get('model_id'):
                    resolved_deployment_id = dep.get('deployment_id')
                    resolved_model_id_for_inference = serving_model_info.get('model_id')
                    break

        if not resolved_deployment_id:
            raise RuntimeError(f"Could not find a ready deployment for model identifier: {model_identifier}")

    except Exception as e:
        raise RuntimeError(f"Error resolving deployment for {model_identifier}: {e}")

    try:
        parameters = TextGenerationParameters(
            max_new_tokens=100,
            min_new_tokens=10,
            temperature=0.7,
            repetition_penalty=1.1
        )

        model = Model(
            model_id=resolved_model_id_for_inference,
            credentials={
                "api_key": api_key,
                "project_id": project_id
            },
            params=parameters,
            deployment_id=resolved_deployment_id,
        )

        response = model.generate_text(prompt=prompt)
        return response

    except Exception as e:
        raise RuntimeError(f"Error invoking model using deployment {resolved_deployment_id}: {e}")
